\begin{proposition}\label{prop:first-variation-criterion}
Let $\Xi$ be admissible, let $\mu,\nu\in\M$ be atomic, and write
$f=f_{\Xi,\mu}$.  Then
\begin{equation}\label{eq:directional-derivative}
 \left.\frac{\dd}{\dd t}\Pp_\Xi((1-t)\mu+t\nu)\right|_{t=0^+}
 =-\int_0^1 f(q)\dd(\nu-\mu)(q).
\end{equation}
In particular, for $Q\in[0,1]$, moving mass $1-m$ from $\mu$ to $Q$
gives, from the left at $m=1$,
\begin{equation}\label{eq:new-point-derivative}
 \left.\frac{\dd}{\dd m}\Pp_\Xi\bigl(m\mu+(1-m)\delta_Q\bigr)
 \right|_{m=1^-}
 =f(Q)-\int_0^1f\dd\mu.
\end{equation}
If $\mu=\sum_{i=0}^rw_i\delta_{q_i}$ with $w_i>0$ and $q_0<\cdots<q_r$, then
moving the location $q_i\in(0,1)$ with all masses and other locations
fixed, or moving mass from $q_j$ to $q_i$, gives, respectively,
\begin{equation}\label{eq:location-derivative}
 \partial_{q_i}\Pp_\Xi(\mu)=-w_i f'(q_i),
 \qquad
 \left.\frac{\dd}{\dd s}\Pp_\Xi\bigl(\mu+s(\delta_{q_i}-\delta_{q_j})\bigr)
 \right|_{s=0}=f(q_j)-f(q_i),
\end{equation}
where the $s$-derivative is two-sided.  Finally, if
\begin{equation}\label{eq:first-variation-criterion}
 f(q)\leq0\quad(0\leq q\leq1),
 \qquad
 \mu\bigl(\{q:f(q)=0\}\bigr)=1,
\end{equation}
then $\mu$ is the unique Parisi measure.
\end{proposition}

\begin{lemma}\label{lem:curvature}
Let $\Xi$ be admissible and $\mu$ atomic, let $X$ be the optimal diffusion
of $\mu$, and set $U_q=u_{\mu,x}(q,X_q)$.  For all
$(q,x)\in[0,1]\times\R$,
\begin{equation}\label{eq:curvature}
 |u_{\mu,x}|\leq1,
 \qquad
 0<u_{\mu,xx}\leq1-u_{\mu,x}^2.
\end{equation}
The process $U$ is a martingale with $U_0=0$, $U_1=\tanh X_1$, and
$\dd U_q=\sqrt{\Xi''(q)}u_{\mu,xx}(q,X_q)\dd B_q$.  Moreover,
$\Gamma=\Gamma_{\Xi,\mu}$ belongs to $C^1([0,1])$ and satisfies $\Gamma(0)=0$,
\begin{equation}\label{eq:Gamma-derivative}
 \Gamma'(q)
 =\Xi''(q)\E u_{\mu,xx}(q,X_q)^2=\Xi''(q)\Gamma_2(q),
\end{equation}
and
\begin{equation}\label{eq:Gamma-curvature}
 0\leq\Gamma'(q)\leq\Xi''(q)\bigl(1-\Gamma(q)\bigr),
 \qquad
 \Gamma(q)\leq\Xi'(q),
 \qquad 0\leq q\leq1.
\end{equation}
\end{lemma}

\begin{definition}\label{def:nondegenerate}
Suppose that $\nu_z$ in \eqref{eq:atomic-measure} is the Parisi measure of
$\Xi$.  We call the $r$-RSB Parisi measure $\nu_z$ \emph{nondegenerate} if:
\begin{enumerate}[label=\textup{(\roman*)}]
 \item $f_{\Xi,\nu_z}\leq0$ on $[0,1]$, with equality exactly at
 $q_0,\ldots,q_r$;
 \item $f_{\Xi,\nu_z}''(q_i)<0$ for $1\leq i\leq r$.
\end{enumerate}
For $r=0$, condition~(ii) is vacuous.
\end{definition}

\begin{proposition}
\label{prop:finite-step-regularity}
For every finite $\mathscr P\subset\{2,4,6,\ldots\}$ and every $r\geq0$,
the map $(\mathbf c,z)\mapsto\Pp_{\Xi_{\mathbf c}}(\nu_z)$ is $C^\infty$ on
$\mathcal C_{\mathscr P}\times\mathcal Z_r$.
\end{proposition}

\begin{lemma}\label{lem:atomic-hessian}
Let $\Xi$ be admissible, and let $z\in\mathcal Z_r$ be a critical point of
$z'\mapsto\Pp_\Xi(\nu_{z'})$.  If $f_{\Xi,\nu_z}''(q_i)<0$ for
$1\leq i\leq r$, then the Hessian $D_z^2\Pp_\Xi(\nu_z)$, which exists by
\zcref{prop:finite-step-regularity}, is positive definite.
\end{lemma}

\begin{lemma}\label{lem:replica-symmetric-seed}
The covariance $\Xi(q)=q^4/16$ has the nondegenerate
replica-symmetric Parisi measure $\delta_0$.
\end{lemma}

\begin{lemma}\label{lem:lower-recursion}
For every sufficiently large even $p$ and every
$(\theta,Q)\in\Theta\times S_p$,
\begin{equation}\label{eq:candidate-decomposition}
 \Pp_p(\theta,Q)
 =
 F(\theta)
 +\mathcal T_p(\theta,Q)
 +\mathcal R_p(\theta,Q),
 \qquad
 \mathcal T_p(\theta,Q)=\frac{1-m}{2}\int_Q^1(1-q)\Psi''(q)\dd q,
\end{equation}
where the remainder $\mathcal R_p=\Pp_p-F-\mathcal T_p$ is $C^4$ on
$\Theta\times S_p$, with
\begin{equation}\label{eq:lower-remainder-bound}
 \max_{|\mathbf j|\leq4}
 \sup_{\Theta\times S_p}
 \bigl|
 \partial_{z,\lambda,m,Q}^{\mathbf j}\mathcal R_p
 \bigr|
 \leq Cp^Ae^{-cp}.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:deficit}
For every sufficiently large even $p$, the magnetization deficit $\mathcal A_p$ is $C^2$
on $\Theta\times S_p$, and, for all $(\theta,Q)\in\Theta\times S_p$,
\begin{align}
 \max_{|\mathbf j|\leq2}
 \bigl|\partial_{z,\lambda,m,Q}^{\mathbf j}\mathcal A_p(\theta,Q)\bigr|
 &\leq Cp^Ae^{-cp},
 \label{eq:endpoint-crude}\\
 cp^{-1/2}e^{-m^2\lambda p/2}
 \leq\mathcal A_p(\theta,Q)
 &\leq Cp^{-1/2}e^{-m^2\lambda p/2}.
 \label{eq:endpoint-two-sided}
\end{align}
Moreover, the mean squared magnetization $\Gamma$ of $\mu_{z,m,Q}$ for $\Psi$
satisfies
\begin{equation}\label{eq:deficit-intermediate}
 1-\Gamma(q)\leq4e^{-m^2(\Psi'(q)-\Psi'(\bar q))/2},
 \qquad \bar q\leq q\leq Q.
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:uniform-reduction}
For every sufficiently large even $p$ and every $\theta\in\Theta$, the
location equation \eqref{eq:top-equation} has exactly one solution $Q=Q_p(\theta)$
in $S_p$.  It lies in the interior of $S_p$ and satisfies
\begin{equation}\label{eq:transition-Q-root}
 C^{-1}p^{-1/2}e^{-m^2\lambda p/2}
 \leq
 1-Q_p(\theta)
 \leq
 Cp^{-1/2}e^{-m^2\lambda p/2}.
\end{equation}
\end{proposition}

\begin{proposition}\label{prop:reduced-functional}
For every sufficiently large even $p$, the following hold.
\begin{enumerate}[label=\textup{(\roman*)}]
 \item The reduced functional $\widehat\Pp_p$ is $C^3$ and satisfies
\begin{equation}\label{eq:envelope}
 \partial_j\widehat\Pp_p(\theta)
 =
 \partial_j\Pp_p\bigl(\theta,Q_p(\theta)\bigr)
 \quad\text{for every coordinate $\theta_j$ of $\theta$}.
\end{equation}
 \item The reduced functional satisfies
\begin{equation}\label{eq:transition-C3-limit}
 \bigl\|\widehat\Pp_p-F\bigr\|_{C^3(\Theta)}
 \leq Cp^Ae^{-cp}.
\end{equation}
\end{enumerate}
\end{proposition}

\begin{proposition}\label{prop:high-overlap-geometry}
For every sufficiently large even $p$ and every
$(\lambda,m)\in\Lambda\times[m_0,1]$, let $f$ and $\Gamma$ be the
first-variation function and the mean squared magnetization of the candidate
minimizer $\mu_p(\lambda,m)$, and let $z=z_p(\lambda,m)$ and
$Q=Q_p(z,\lambda,m)$.  Then $\bar q<\hat q_p<Q$,
\begin{equation}\label{eq:intermediate-negative}
 f(q)\leq-\gamma,
 \qquad
 \bar q\leq q\leq\hat q_p,
\end{equation}
with $\gamma$ from \eqref{eq:cutoff-choice}, and
\begin{equation}\label{eq:Gamma-slope-tail}
 \Gamma'(q)\leq\frac12,
 \qquad
 \hat q_p\leq q\leq1.
\end{equation}
Consequently, $f$ is strictly increasing on $[\hat q_p,Q]$ and strictly
decreasing on $[Q,1]$, and $f''(Q)<0$.
\end{proposition}

\begin{corollary}\label{cor:global-sign}
In the setting of \zcref{prop:high-overlap-geometry}, if $f(Q)<0$, then
$f\leq0$ on $[0,1]$ and $\{f=0\}=\supp\nu_z$; if $f(Q)=0$, then $f\leq0$
on $[0,1]$ and $\{f=0\}=\supp\nu_z\cup\{Q\}$.
\end{corollary}

\begin{proposition}\label{prop:iteration}
For every integer $k\geq0$, there exist even integers
$4=p_0<p_1<\cdots<p_k$ and positive coefficients $c_0,\ldots,c_k$ such that
$\sum_{j=0}^kc_jq^{p_j}$ has a nondegenerate $k$-RSB Parisi measure.
\end{proposition}

\begin{lemma}\label{lem:sharp-first-variation}
Let $\Xi$ be admissible, let $\mu,\nu\in\M$ be atomic, let $X$ be the
optimal diffusion of $\mu$, and set
$I=\int_0^1\Xi''(q)(\alpha_\nu-\alpha_\mu)(q)u_{\mu,x}(q,X_q)\dd q$.  Then
\begin{equation}\label{eq:sharp-first-variation}
 \Pp_\Xi(\nu)-\Pp_\Xi(\mu)
 \geq-\int_0^1f_{\Xi,\mu}\dd(\nu-\mu)
 +\E\bigl[\log\cosh(X_1+I)-\log\cosh X_1-\tanh(X_1)I\bigr],
\end{equation}
and the expectation on the right is nonnegative.
\end{lemma}

\begin{lemma}\label{lem:temperature-mass-diffusion}
In the setting of \zcref{lem:temperature-mass-scaling}, let $Y$ be the
optimal diffusion of $(m^2\Xi,\nu)$, and let
$X^\circ=X^{\mathfrak d^\circ_{\nu,m}}$ be driven by the same Brownian
motion.  Then $X^\circ=m^{-1}Y$ on $[0,q_{\mathrm c}]$, and
\begin{equation}\label{eq:temperature-mass-Gamma-f}
 \Gamma^{\mathfrak d^\circ_{\nu,m}}=\Gamma_{m^2\Xi,\nu},
 \qquad
 f^{\mathfrak d^\circ_{\nu,m}}=\frac1{m^2}f_{m^2\Xi,\nu}
 \qquad\text{on }[0,q_{\mathrm c}].
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:deficit-representation}
For every sufficiently large even $p$ and every
$(\theta,Q)\in\Theta\times S_p$, let $X$ and $\Gamma$ be the optimal
diffusion and the mean squared magnetization of
$\mu_{z,m,Q}$ for $\Psi$, and let $v_t=T_{m,W_p-t}\log\cosh$ for
$0\leq t\leq W_p$.  For $\bar q<q\leq Q$, set
$t=\Psi'(q)-\Psi'(\bar q)$.  Then, conditionally on $X_{\bar q}=x$, the law
of $X_q$ is $K_{m,t,v_t}(x,\cdot)$, and
\begin{equation}\label{eq:deficit-representation}
 1-\Gamma(q)=\E\bigl[1-v_t'(X_q)^2\bigr].
\end{equation}
At $q=Q$, we have $t=W_p$ and $v_{W_p}'=\tanh$, so $1-\Gamma(Q)=\E\sech^2(X_Q)$.
\end{lemma}

\begin{lemma}\label{lem:large-V}
Let $I\subset(0,1]$ be compact, and let $c=\frac12(\min I)^2$.  There
exists $\overline V\geq1$, depending only on $I$, with the following
property.  For every integer $\ell\geq0$, there exists $C_\ell<\infty$,
depending only on
$I$ and $\ell$, such that, for all $m\in I$, $V\geq\overline V$, and
$x\in\R$,
\begin{equation}\label{eq:large-V}
 (T_{m,V}\log\cosh)(x)
 =\frac{mV}{2}+\left(\frac1m-1\right)\log2
 +\frac1m\log\cosh(mx)+\mathcal E_{m,V}(x),
\end{equation}
where
\begin{equation}\label{eq:large-V-error}
 \max_{i+j+k\leq\ell}\sup_{x\in\R}
 \left|
 \partial_x^i\partial_m^j\partial_V^k
 \mathcal E_{m,V}(x)
 \right|
 \leq C_\ell V^\ell e^{-cV}.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:tanh-comparison}
Let $0<m\leq1$ and $V\geq0$, and let $v=T_{m,V}\log\cosh$.  Then
$|v'(y)|\geq\tanh(m|y|)$ for all $y\in\R$; in particular,
$1-v'(y)^2\leq\sech^2(my)$.
\end{lemma}

\begin{lemma}\label{lem:doob-kernel}
Let $0<m\leq1$ and $W>0$, and set $v_t=T_{m,W-t}\log\cosh$ for
$0\leq t\leq W$.  For $t\in(0,W]$ and $x\in\R$,
\begin{equation}\label{eq:exact-Doob}
 K_{m,t,v_t}(x,\dd y)
 =\mathsf p_t(x,y)\,\frac{e^{mv_t(y)}}{e^{mv_0(x)}}\dd y.
\end{equation}
Let
\begin{equation}\label{eq:Kinfty-mixture}
 K^\infty_t(x,\dd y)
 =\mathsf p_t(x,y)\,e^{-m^2t/2}\,\frac{\cosh(my)}{\cosh(mx)}\dd y
 =\frac{e^{mx}\mathsf p_t(x+mt,y)+e^{-mx}\mathsf p_t(x-mt,y)}{2\cosh(mx)}\dd y.
\end{equation}
Then, for $t\in(0,W]$ and $x\in\R$,
\begin{equation}\label{eq:Doob-comparison}
 \frac14K^\infty_t(x,\cdot)\leq K_{m,t,v_t}(x,\cdot)\leq4K^\infty_t(x,\cdot).
\end{equation}
\end{lemma}
